import React, { useEffect, useState } from 'react';
import axios from 'axios';
import styles from './RequestQueue.module.css';

function RequestQueue({ user }) {
  const [requests, setRequests] = useState([]);

  useEffect(() => {
    axios.get('http://localhost:5000/api/requests')
      .then(res => setRequests(res.data))
      .catch(() => setRequests([]));
  }, []);

  const acceptRequest = async (requestId) => {
    try {
      await axios.post('http://localhost:5000/api/requests/accept', { requestId });
      alert('Request accepted!');
    } catch {
      alert('Failed to accept request');
    }
  };

  const notifyStudent = async (requestId) => {
    try {
      await axios.post('http://localhost:5000/api/requests/notify', { requestId });
      alert('Email sent!');
    } catch {
      alert('Failed to send email');
    }
  };

  return (
    <div className={styles.container}>
      <div className={styles.title}>Request Queue</div>
      <ul className={styles.list}>
        {requests.map(req => (
          <li className={styles.item} key={req._id}>
            <span className={styles.info}>
              <strong>Book:</strong> {req.book?.title || 'N/A'} | <strong>Student:</strong> {req.student?.name || 'N/A'} | <strong>Status:</strong> {req.status}
            </span>
            {user?.role === 'librarian' && req.status === 'pending' && (
              <button className={styles.button} onClick={() => acceptRequest(req._id)}>Accept</button>
            )}
            {user?.role === 'librarian' && req.status === 'accepted' && (
              <button className={styles.button} onClick={() => notifyStudent(req._id)}>Send Reminder</button>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default RequestQueue;
